import torch


def run(scalar, inp):
    return torch.remainder(scalar, inp)


def gen_inputs(ctx, device):
    import torch

    shape = tuple(ctx["inp__shape"])
    dtype = ctx["inp__dtype"]
    if isinstance(dtype, str):
        dtype = getattr(torch, dtype)
    info = torch.iinfo(dtype)
    t = torch.randint(info.min, info.max, shape, dtype=dtype, device="cpu").to(device)
    t = torch.where(t == 0, torch.ones_like(t), t)
    return {"inp": t}
